(()=>{const $=id=>document.getElementById(id);let name='',chosen='',pending='';const headers={lobby:['L&B EINSATZLOBBY','Anmeldung vor dem gemeinsamen Start','LOBBY'],intro:['L&B PRESSEARCHIV // BESTAND 2014','Rekonstruiertes Pressearchiv','ARCHIV'],group:['SEGMENTZUWEISUNG','Arbeitsbereiche zuordnen','A–V'],archive:['ARCHIVSEGMENT','Originalmaterial und zugeordnete Aufzeichnungen','GRUPPE']};const stages={lobby:['01 / 04 · LOBBY','Die Lobby registriert ein Gerät. Die Leitung kann den gemeinsamen Start auslösen.'],intro:['02 / 04 · PRESSEARCHIV','Originalansicht und Transkript gehören zum selben Dokument. Die Rätselantwort ist in dieser Vorschau ausgelassen.'],group:['03 / 04 · SEGMENTZUWEISUNG','Wählen Sie A, B, C, D oder V. Unterschiedliche Bereiche erhalten unterschiedliche Unterlagen. E folgt später.'],archive:['04 / 04 · GRUPPENARCHIV','Navigation und Inhalt wechseln mit der Gruppe. Hier sehen Sie ausschließlich fiktive Dokumente.']};function view(which){['lobby','intro','group','archive'].forEach(id=>$(id+'View').classList.toggle('hidden',id!==which));const h=headers[which];$('mainTitle').textContent=which==='archive'?`ARCHIVSEGMENT ${chosen}`:h[0];$('mainSubtitle').textContent=h[1];$('statusBadge').textContent=which==='archive'?`GRUPPE ${chosen}`:h[2];$('step-label').textContent=stages[which][0];$('guide-text').textContent=stages[which][1];window.scrollTo({top:0,behavior:'smooth'})}function groups(){const el=$('groupCards');el.innerHTML='';['A','B','C','D','V'].forEach(g=>{const b=document.createElement('button');b.type='button';b.className='group-card'+(chosen===g?' selected':'');b.innerHTML=`<span>GRUPPE ${g}</span><strong>BEISPIELBEREICH</strong>`;b.onclick=()=>{pending=g;$('confirmText').textContent=`Gruppe ${g} auswählen?`;$('groupConfirm').classList.remove('hidden')};el.appendChild(b)})}function doc(key){const titles={report:'Beispielprotokoll',timeline:'Zeitlinie',notice:'Hinweis'};const descriptions={report:`Dieser neutrale Auszug demonstriert die Lesefläche für Gruppe ${chosen}. Im Original sind hier gruppenspezifische Quellen eingebunden.`,timeline:'Eine zeitliche Ordnung kann andere Unterlagen ergänzen. Auch dieser Text ist erfunden und enthält keine Hinweise auf den Spielverlauf.',notice:'Die konkrete Freigabe hängt im Originalsystem von Phase, Gruppenstand und Zeitfenster ab.'};$('archiveText').innerHTML=`<div class="archive-prose"><small>ÖFFENTLICHE DEMO // GRUPPE ${chosen}</small><h3>${titles[key]}</h3><p>${descriptions[key]}</p><aside>Die echte Oberfläche behält Navigation und Lesebereich bei. Diese Beispielinhalte ersetzen alle Originalunterlagen.</aside></div>`;document.querySelectorAll('#archiveNav button').forEach(b=>b.classList.toggle('active',b.dataset.doc===key))}$('lobbyForm').onsubmit=e=>{e.preventDefault();name=$('lobbyUsername').value.trim();if(name.length<2)return;$('lobbyForm').classList.add('hidden');$('lobbyWaiting').classList.remove('hidden');$('joinedUsername').textContent=name};$('startDemo').onclick=()=>view('intro');$('toGroups').onclick=()=>{groups();view('group')};$('showImages').onclick=()=>{$('articleImages').classList.remove('hidden');$('articleTranscript').classList.add('hidden');$('showImages').classList.add('active');$('showTranscript').classList.remove('active');$('showImages').setAttribute('aria-selected','true');$('showTranscript').setAttribute('aria-selected','false')};$('showTranscript').onclick=()=>{$('articleImages').classList.add('hidden');$('articleTranscript').classList.remove('hidden');$('showImages').classList.remove('active');$('showTranscript').classList.add('active');$('showImages').setAttribute('aria-selected','false');$('showTranscript').setAttribute('aria-selected','true')};$('confirmGroup').onclick=()=>{chosen=pending;$('groupConfirm').classList.add('hidden');$('archiveTitle').textContent=`ARCHIVSEGMENT ${chosen}`;$('groupBadge').textContent=`GRUPPE ${chosen}`;doc('report');view('archive')};$('cancelGroup').onclick=()=>$('groupConfirm').classList.add('hidden');$('backGroups').onclick=()=>{groups();view('group')};document.querySelectorAll('#archiveNav button').forEach(b=>b.onclick=()=>doc(b.dataset.doc));$('reset').onclick=()=>{chosen='';pending='';name='';$('lobbyUsername').value='';$('lobbyForm').classList.remove('hidden');$('lobbyWaiting').classList.add('hidden');view('lobby')};view('lobby')})();
